import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type StressBellyProps = Record<string, any>;

const StressBelly: React.FC<StressBellyProps> = ({
  title = "Stress Belly",
  titleColor = "#d32f2f",
  bellyColor = "#ffccaa",
  backgroundColor = "#ffffff",
  transparentBackground = true,
  durationInSeconds = 5,
  bellyScale = 1,
  growthIntensity = 0.1,
}) => {
  useFontLoader(["Luckiest Guy"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Handle transparency
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // 1. Pop-in Entrance (Spring)
  const entrance = spring({
    frame,
    fps,
    config: {
      damping: 10,
      stiffness: 100,
      mass: 0.5,
    },
  });

  // 2. Continuous Growth (Linear Interpolation)
  // Starts after the main pop has settled slightly, or runs throughout.
  // Running throughout adds to the chaotic/bloating feel.
  const growth = interpolate(
    frame,
    [0, durationInSeconds * fps],
    [1, 1 + growthIntensity],
    { extrapolateRight: "clamp" }
  );

  // Combine transforms
  // Base scale * Entrance (0->1) * Growth (1->1.X)
  const totalScale = bellyScale * entrance * growth;

  // Responsive calculations
  const baseSize = Math.min(width, height) * 0.6; // Belly takes up 60% of shortest dimension
  const fontSize = baseSize * 0.18; // Text size relative to belly

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        justifyContent: "center",
        alignItems: "center",
        fontFamily: "Luckiest Guy",
        overflow: "hidden", // Prevent growth from causing scrollbars if it gets too big
      }}
    >
      <div
        style={{
          width: baseSize,
          height: baseSize,
          position: "relative",
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          transform: `scale(${totalScale})`,
          // Transition: none is critical for Remotion frame-by-frame control
          transition: "none", 
        }}
      >
        {/* SVG Belly Graphic */}
        <svg
          viewBox="0 0 200 200"
          style={{
            width: "100%",
            height: "100%",
            position: "absolute",
            top: 0,
            left: 0,
            overflow: "visible",
          }}
        >
          {/* Main Belly Shape - Slightly bottom-heavy circle for "sag" effect */}
          <path
            d="M 100 10 
               C 160 10, 190 50, 190 110 
               C 190 170, 150 190, 100 190 
               C 50 190, 10 170, 10 110 
               C 10 50, 40 10, 100 10 Z"
            fill={bellyColor}
            stroke="none"
          />
          
          {/* Belly Button - Simple friendly curve */}
          <path
            d="M 95 135 Q 100 140 105 135"
            fill="none"
            stroke="#e5b095" // Slightly darker skin tone
            strokeWidth="3"
            strokeLinecap="round"
            style={{ opacity: 0.6 }}
          />
        </svg>

        {/* Text Overlay */}
        <div
          style={{
            zIndex: 1,
            color: titleColor,
            fontSize: fontSize,
            textAlign: "center",
            width: "90%",
            lineHeight: 1,
            textShadow: "2px 2px 0px rgba(0,0,0,0.1)", // Subtle depth
            transform: "translateY(-10%) rotate(-5deg)", // Slight tilt for cartoon feel
          }}
        >
          {title}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default StressBelly;